svg.script:
(() => {
  const svgNS = 'http://www.w3.org/2000/svg';
  const route = document.getElementById('ruta');
  const road = document.getElementById('carretera');
  const rails = document.getElementById('barandas');
  const car = document.getElementById('carro');
  const carScale = document.getElementById('carro-scale');
  const length = route.getTotalLength();
  const carWidth = 92;
  const create = (tag, attrs) => {
    const node = document.createElementNS(svgNS, tag);
    for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
    return node;
  };
  const pointAt = (s) => route.getPointAtLength(Math.max(0, Math.min(length, s)));
  const frameAt = (s) => {
    const p = pointAt(s);
    const before = pointAt(s - 1.5);
    const after = pointAt(s + 1.5);
    const dx = after.x - before.x;
    const dy = after.y - before.y;
    const mag = Math.hypot(dx, dy) || 1;
    const tx = dx / mag;
    const ty = dy / mag;
    return { x: p.x, y: p.y, tx, ty, nx: -ty, ny: tx };
  };
  const widthAt = (f) => Math.max(6, 6 + 84 * Math.pow(1 - f, .8) + 1.5 * Math.sin(f * 14) * (1 - f));
  const sampleCount = Math.ceil(length / 1.8);
  const samples = [];
  for (let i = 0; i <= sampleCount; i++) {
    const f = i / sampleCount;
    samples.push({ ...frameAt(length * f), f, width: widthAt(f) });
  }
  const offsetPoint = (p, side, extra = 0) => {
    const d = p.width / 2 + extra;
    return [p.x + p.nx * d * side, p.y + p.ny * d * side];
  };
  const polyPoints = (side, extra) => samples.map((p) => offsetPoint(p, side, extra).map((v) => v.toFixed(2)).join(',')).join(' ');
  const border = create('polygon', { points: `${polyPoints(-1, 3)} ${polyPoints(1, 3).split(' ').reverse().join(' ')}`, fill: '#f3e9d0', opacity: '.86' });
  const asphalt = create('polygon', { points: `${polyPoints(-1, 0)} ${polyPoints(1, 0).split(' ').reverse().join(' ')}`, fill: '#686e63' });
  road.append(border, asphalt);
  const edgePaths = [-1, 1].map((side) => {
    const d = samples.map((p, i) => {
      const q = offsetPoint(p, side);
      return `${i ? 'L' : 'M'}${q[0].toFixed(2)} ${q[1].toFixed(2)}`;
    }).join(' ');
    const path = create('path', { d, fill: 'none', stroke: '#f5ebd1', 'stroke-linecap': 'round' });
    road.append(path);
    return path;
  });
  edgePaths.forEach((path, sideIndex) => {
    const side = sideIndex === 0 ? -1 : 1;
    for (let i = 0; i < samples.length - 1; i++) {
      const p = samples[i];
      const a = offsetPoint(p, side);
      const b = offsetPoint(samples[i + 1], side);
      const segment = create('path', { d: `M${a[0]} ${a[1]}L${b[0]} ${b[1]}`, stroke: '#f5ebd1', 'stroke-width': Math.max(.45, 2.8 * (1 - p.f) + .35), 'stroke-opacity': .95 - .72 * p.f, 'stroke-linecap': 'round' });
      road.append(segment);
    }
  });
  const shadowPoints = samples.map((p) => [p.x - p.nx * p.width * .46, p.y - p.ny * p.width * .46]);
  const innerShadowPoints = samples.map((p) => [p.x - p.nx * p.width * .25, p.y - p.ny * p.width * .25]);
  const shadow = create('polygon', { points: `${shadowPoints.map((p) => p.join(',')).join(' ')} ${innerShadowPoints.reverse().map((p) => p.join(',')).join(' ')}`, fill: '#354039', opacity: '.1' });
  road.append(shadow);
  let dashAt = 0;
  while (dashAt < length - 2) {
    const f = dashAt / length;
    const p = frameAt(dashAt);
    const w = widthAt(f);
    const dashLength = Math.max(.8, w * .115);
    const a = pointAt(dashAt - dashLength / 2);
    const b = pointAt(dashAt + dashLength / 2);
    road.append(create('path', { d: `M${a.x} ${a.y}L${b.x} ${b.y}`, fill: 'none', stroke: '#f5efd9', 'stroke-width': Math.max(.45, w * .055), 'stroke-linecap': 'round', opacity: .9 - .48 * f }));
    dashAt += 2.6 + 15 * (1 - f);
  }
  const curvatureAt = (s) => {
    const a = frameAt(s - 4);
    const b = frameAt(s + 4);
    return { cross: a.tx * b.ty - a.ty * b.tx, strength: Math.abs(a.tx * b.ty - a.ty * b.tx) / 8 };
  };
  let railPoints = [];
  const flushRail = () => {
    if (railPoints.length < 2) { railPoints = []; return; }
    const d = railPoints.map((p, i) => `${i ? 'L' : 'M'}${p.x.toFixed(2)} ${p.y.toFixed(2)}`).join(' ');
    const railPath = create('path', { d, fill: 'none', stroke: '#eee6d0', 'stroke-width': '2.4', 'stroke-linecap': 'round', 'stroke-linejoin': 'round' });
    const railShadow = create('path', { d, fill: 'none', stroke: '#53695a', 'stroke-width': '5', 'stroke-linecap': 'round', 'stroke-linejoin': 'round', opacity: '.9' });
    rails.append(railShadow, railPath);
    railPoints = [];
  };
  let railStep = 0;
  while (railStep < length) {
    const f = railStep / length;
    const p = frameAt(railStep);
    const curve = curvatureAt(railStep);
    if (curve.strength > .0015) {
      const side = curve.cross > 0 ? -1 : 1;
      const d = p.width / 2 + 3.5;
      const x = p.x + p.nx * d * side;
      const y = p.y + p.ny * d * side;
      railPoints.push({ x, y });
      const postHeight = 2 + 11 * (1 - f);
      rails.append(create('line', { x1: x, y1: y, x2: x - p.tx * .8, y2: y - postHeight, stroke: '#f0e8d2', 'stroke-width': Math.max(.55, 1.8 * (1 - f)), 'stroke-linecap': 'round' }));
    } else flushRail();
    railStep += 3 + 14 * (1 - f);
  }
  flushRail();
  let started = 0;
  let previousAngle = 0;
  const animateCar = (now) => {
    if (!started) started = now;
    const elapsed = (now - started) % 12000;
    const f = elapsed / 12000;
    const s = length * f;
    const p = frameAt(s);
    const width = widthAt(f);
    const laneOffset = width * .22;
    const x = p.x + p.nx * laneOffset;
    const y = p.y + p.ny * laneOffset;
    const desired = Math.atan2(p.ty, p.tx) * 180 / Math.PI + 90;
    const bounded = Math.max(-6, Math.min(6, desired));
    previousAngle += (bounded - previousAngle) * .13;
    const scale = .45 * width / carWidth;
    const bounce = Math.sin(elapsed / 350 * Math.PI * 2) * 1.5;
    car.setAttribute('transform', `translate(${x.toFixed(2)} ${(y + bounce).toFixed(2)}) rotate(${previousAngle.toFixed(2)})`);
    carScale.setAttribute('transform', `scale(${scale.toFixed(4)})`);
    requestAnimationFrame(animateCar);
  };
  requestAnimationFrame(animateCar);
})();
